CREATE TABLE IF NOT EXISTS iam.authorization_grant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_assignment_id uuid NOT NULL REFERENCES iam.role_assignment(id) ON DELETE RESTRICT, status varchar(16) NOT NULL DEFAULT 'ACTIVE', valid_from timestamptz NOT NULL, valid_to timestamptz, granted_by uuid, grant_reason text NOT NULL, revoked_by uuid, revoked_at timestamptz, revoke_reason text, created_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS iam.grant_capability (grant_id uuid NOT NULL REFERENCES iam.authorization_grant(id) ON DELETE RESTRICT, capability_id uuid NOT NULL REFERENCES iam.capability(id) ON DELETE RESTRICT, PRIMARY KEY(grant_id, capability_id));
CREATE TABLE IF NOT EXISTS iam.grant_scope (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grant_id uuid NOT NULL REFERENCES iam.authorization_grant(id) ON DELETE RESTRICT, scope_dimension varchar(16) NOT NULL, scope_type varchar(24) NOT NULL, org_unit_id uuid REFERENCES org.org_unit(id) ON DELETE RESTRICT, org_unit_type_snapshot varchar(16));
CREATE TABLE IF NOT EXISTS iam.grant_field_clearance (grant_id uuid NOT NULL REFERENCES iam.authorization_grant(id) ON DELETE RESTRICT, field_classification varchar(32) NOT NULL, PRIMARY KEY(grant_id, field_classification));
